/**Custom Code*/
Object current = param(1);
treenode activity = param(2);
Token token = param(3);
treenode processFlow = ownerobject(activity);


Table wyniki_drony = Table("Wyniki_czasy_dronow_w3");
double V = getvarnum(token.dron,"maxspeed");
double kc = Table("Dane")[34][2];

wyniki_drony.addRow();
wyniki_drony[wyniki_drony.numRows][1] = token.dron.name;
wyniki_drony[wyniki_drony.numRows][3] = time - token.t_start;

double x1 = token.d_start_x;
double y1 = token.d_start_y;
double x2 = token.dron.location.x;
double y2 = token.dron.location.y;
double dist = Math.sqrt(Math.pow((x2-x1),2)+Math.pow((y2-y1),2));
wyniki_drony[wyniki_drony.numRows][5] = dist;
wyniki_drony[wyniki_drony.numRows][6] = token.Waga_total;
wyniki_drony[wyniki_drony.numRows][7] = V;


double Emp = -0.0012*Math.pow(V,5) + 0.0958*Math.pow(V,4) - 2.9107*Math.pow(V,3) + 43.463*Math.pow(V,2) - 334.74*V + 1292.8;
double Emp2 = Emp*token.dron.Vpayload/token.dron.Vground;
double Emp3 = Emp2*(1+kc*(Math.pow(Math.fabs(token.dron.WI_)/token.dron.Vpayload,2)));



wyniki_drony[wyniki_drony.numRows][8] = Emp3;

if (wyniki_drony[wyniki_drony.numRows][2]==0)
{
	wyniki_drony[wyniki_drony.numRows][9] = Emp3*wyniki_drony[wyniki_drony.numRows][5];
}
else
{
	wyniki_drony[wyniki_drony.numRows][9] = Emp3*wyniki_drony[wyniki_drony.numRows][4];
}
